#pragma once
#include <GL/glew.h>

namespace bibo
{
	namespace world
	{
		/**
		* Layers of the material textures (the shaders use the same numbers)
		*/
		enum MaterialLayer
		{
			MATERIAL_SNOW,
			MATERIAL_FOREST_FLOOR, //moss, soil and fallen needles
			MATERIAL_DIRT, //the trail with pebbles
			MATERIAL_ROCK, //granite with cracks and lichen
			MATERIAL_SAND,
			MATERIAL_BARK,
			MATERIAL_NEEDLES, //spruce branches
			MATERIAL_LEAVES,
			MATERIAL_LAYER_COUNT
		};

		/**
		* The PBR materials of the world, generated by the graphics card when the game starts (Shader/material_generator.frag):
		* two texture arrays with a layer per material, one with the color (sRGB) and roughness, the other with the tangent space
		* normal (xy), the height and the ambient occlusion. All of them repeat seamlessly.
		*/
		class MaterialTextures
		{
		public:
			/**
			* @param size Width and height of the textures in texels
			*/
			explicit MaterialTextures(int size);
			~MaterialTextures();
			MaterialTextures(const MaterialTextures&) = delete;
			MaterialTextures& operator=(const MaterialTextures&) = delete;

			/**
			* Binds the color and the normal texture array to their texture units (render::TextureUnit)
			*/
			void bind() const;
			GLuint getAlbedo() const { return albedo; }
			GLuint getNormal() const { return normal; }
			int getSize() const { return size; }

		private:
			int size;
			GLuint albedo = 0, normal = 0;
		};
	}
}
